# Cards: the tissue scenes (feather, flight muscle, hollow bone, retina) and the park-level bird card.
from robin_lib import *
def T(id, title, scale, parents, summary, basics, deeper, expert, facts, **kw): return N(id, title, 'structure', scale, parents, summary, basics, deeper, expert, facts, **kw)

T('robin_feather_scene', 'Inside a feather', 1e-3, ['robin_prim'], 'A flight feather is a tree: a shaft, side branches (barbs), twigs (barbules) and tiny hooks that zip the vane together.',
  'Look closely at a feather and you find a branching structure. From the central shaft (the rachis) the side branches (barbs) grow out in a row, and from each barb grow even finer twigs, the barbules. The barbules of neighbouring barbs overlap, and tiny hooks hold them together, so the vane is a smooth sheet that air cannot go through. If you pull it apart, the hooks re-engage when you stroke it back, which is what a bird does when it preens.',
  'The barbules on a flight feather of species from a hummingbird to a condor are spaced only 8 to 16 micrometres apart. The shaft is made of bundles of 3-nanometre keratin filaments embedded in an amorphous keratin matrix.',
  'Sizes drawn in the scene: only the barbule spacing (8 to 16 µm) is a published measurement; the barb and barbule lengths and thicknesses, and the number of hooks, are illustrative.',
  [['Barbule spacing', '8 to 16 µm (J. R. Soc. Interface 2025)'], ['Keratin filament', '3 nm diameter, in the shaft\'s cortex']], refs=[R_PRO], ext=[JRSI, WFE, WFF], parts=['robin_barb', 'robin_barbule', 'robin_hooklet', 'robin_pigment_granule'])
T('robin_barb', 'Barb', 5e-4, ['robin_feather_scene'], 'A barb is one of the side branches of a feather\'s shaft; a row of them makes the vane.', 'Each barb is a thin rod that grows from the shaft at an angle. A feather vane has hundreds of them side by side.', 'Along each barb, barbules branch to both sides.', 'The lengths and thicknesses drawn are illustrative.', [['Role', 'branch of the rachis, bears barbules']], refs=[R_PRO], ext=[WFE])
T('robin_barbule', 'Barbule: the hooked twigs', 6e-6, ['robin_feather_scene'], 'The barbules are the fine twigs of the barbs; the hooks of one barbule catch the next.', 'Each barb carries a row of barbules on each side. The barbules that face the tip of the feather have little hooks; those that face the base have a ridge where the hooks catch. The result is a zip. A barbule is a few micrometres thick and made of dead cells full of keratin. Use the button to see the molecule that links the keratin together.', 'Neighbouring barbules sit 8 to 16 micrometres apart.', 'Each barbule is a chain of dead, keratin-filled cells; the keratin is held together by sulfur bridges.',
  [['Spacing', '8 to 16 µm (J. R. Soc. Interface 2025)'], ['Material', 'beta-keratin']], refs=[R_PRO], ext=[JRSI, WFE, KER], related=['robin_keratin'])
T('robin_hooklet', 'Hooklets (barbicels)', 2e-6, ['robin_feather_scene'], 'The tiny hooks on the barbules that grip the next barbule like the loops of a zip.', 'At the end of a barbule are minute hooks, barbicels, that catch on the ridge of the next barbule. Down feathers lack them, so their barbules float free.', 'This is what turns a loose set of branches into a continuous vane.', 'The hooklets are drawn illustratively: their size and number are not measured.', [['Role', 'interlock neighbouring barbules']], refs=[R_PRO], ext=[WFE])
T('robin_pigment_granule', 'Pigment granules', 1e-6, ['robin_feather_scene'], 'Brown and black feather colour comes from granules of melanin inside the barbs.', 'Colour in a feather is mostly made by pigment. The brown of a robin\'s back is melanin, in small granules inside the barbs and barbules. Use the button to see a molecule on the way to melanin.', 'Melanin is made from the amino acid tyrosine through L-DOPA. Whether the orange of the breast is a type of melanin, phaeomelanin, or a carotenoid is not settled.', 'The granule size and number drawn are illustrative.', [['Pigment', 'melanin (back); breast unresolved']], cert='C2', refs=[R_PRO], ext=[DEL, WFE], related=['robin_pigment'])
T('robin_flight_muscle_scene', 'Inside the flight muscle', 1e-4, ['robin_pectoralis'], 'The flight muscle is a bundle of long fibres, packed with energy-making mitochondria and fed by many fine blood vessels.', 'A muscle is made of long cells called fibres. In a flight muscle each fibre is packed with mitochondria, the parts of the cell that burn fuel with oxygen to make the energy molecule ATP. Between the fibres run fine blood vessels. Click a mitochondrion and press the button to see ATP.', 'The fibres contract by filaments sliding past each other. The energy comes from ATP, made in the mitochondria and used by the motor protein myosin.', 'Sizes in the scene are illustrative; the numbers of fibres and mitochondria drawn are for clarity.', [['Fuel molecule', 'ATP']], refs=[R_ATP, R_ACON], ext=[FLY], related=['skeletal_muscle_fiber', 'muscle_contraction', 'sarcomere'], parts=['robin_muscle_fibre', 'robin_mito'])
T('robin_muscle_fibre', 'Muscle fibre', 5e-5, ['robin_flight_muscle_scene'], 'A flight muscle fibre is one long cell, many times longer than it is wide.', 'Each fibre is a single long cell with many nuclei, filled with bundles of contracting filaments. It is surrounded by capillaries.', 'Contraction comes from the sliding of thick and thin filaments.', 'The fibre drawn is a tube; real fibres are more varied in size.', [['Cell', 'one long, multinucleate cell']], refs=[R_ACON], ext=[FLY], related=['skeletal_muscle_fiber'])
T('robin_mito', 'Mitochondria', 1e-6, ['robin_flight_muscle_scene'], 'Mitochondria make most of the muscle\'s ATP by burning fuel with oxygen.', 'Mitochondria are the powerhouses of the cell. Flight uses a lot of energy, so flight muscle is packed with them. They make the energy molecule ATP.', 'Oxidative phosphorylation across their inner membrane makes most of the ATP.', 'Their size and number in the scene are illustrative.', [['Product', 'ATP']], refs=[R_ATP, R_OX], ext=[FLY], related=['bio_atp_energy_coupling'])
T('robin_bone_scene', 'Inside a hollow bone', 1e-3, ['robin_humerus'], 'A hollow bone is a thin wall of dense bone round an air-filled space braced by struts.', 'A cut across a hollow bird bone shows a thin ring of hard bone round an empty (air-filled) space, crossed by thin struts like those in a bridge. The wall is made of bone cells in a framework of protein and mineral.', 'Bone cells (osteocytes) live in tiny holes in the wall and keep it alive. The struts stiffen the tube against bending and crushing.', 'Sizes in the scene are illustrative.', [['Wall', 'dense (compact) bone'], ['Space', 'air-filled in a pneumatic bone']], refs=[R_BONE, R_ABONE], ext=[WBA], related=['compact_bone', 'long_bone'], parts=['robin_bone_wall', 'robin_bone_strut', 'robin_osteocyte'])
T('robin_bone_wall', 'Wall of compact bone', 5e-4, ['robin_bone_scene'], 'The thin, dense wall of a hollow bone.', 'The wall is dense bone that carries most of the load. Because it is far from the centre of the tube, it makes the tube stiff for little weight.', 'Bone is a composite of mineral and protein fibres.', 'The thickness is illustrative.', [['Type', 'compact bone']], refs=[R_BONE], ext=[WBA], related=['compact_bone'])
T('robin_bone_strut', 'Strut (trabecula)', 2e-4, ['robin_bone_scene'], 'Thin struts crossing the hollow of a bone, like the braces in a bridge.', 'Thin rods of bone cross the hollow space inside many bird bones. They brace the wall against bending and buckling.', 'Their arrangement follows the loads on the bone.', 'Drawn as a random set of thin rods.', [['Role', 'brace the wall']], refs=[R_BONE], ext=[WBA], related=['spongy_bone'])
T('robin_osteocyte', 'Bone cell (osteocyte)', 2e-5, ['robin_bone_scene'], 'The living cell inside a bone, in a tiny pocket of the hard wall.', 'Osteocytes are the long-lived cells of bone. Each sits in a small space and reaches out to its neighbours with fine arms. Use the button to look inside a cell.', 'They sense strain and direct the repair of bone.', 'Drawn as small ovals; the size is illustrative.', [['Cell type', 'osteocyte']], refs=[R_BONE], ext=[WBA], related=['bone_tissue'])
T('robin_retina_scene', 'Inside the retina', 2e-4, ['robin_retina'], 'The retina is a screen of light-sensing cells; a protein called cryptochrome is one candidate for a magnetic sensor.', 'Light entering the eye falls on the retina, which is made of layers of cells. The light-sensing cells, the photoreceptors, hold the molecule retinal, which changes shape when it catches a photon. Some of the retina\'s proteins, the cryptochromes, may help the robin sense Earth\'s magnetic field; that is an unproven idea.', 'The photoreceptors send signals through other retinal neurons to the optic nerve. A bird\'s retina is largely free of blood vessels; it is fed from the choroid and the pecten.', 'The scene is a schematic: the cell shapes and sizes are illustrative, and the place of cryptochrome in a particular cell type is not drawn as a measurement.', [['Light-catching molecule', 'retinal'], ['Magnetic candidate', 'cryptochrome 4 with FAD (hypothesis)']], cert='C3', refs=[R_VIS], ext=[XU, WONG, PECT], related=['retina', 'rod_cell', 'cone_cell', 'robin_compass'], parts=['robin_photoreceptor', 'robin_cryptochrome'])
T('robin_photoreceptor', 'Photoreceptor cell', 5e-5, ['robin_retina_scene'], 'A photoreceptor catches light with the molecule retinal and turns it into a nerve signal.', 'Photoreceptors are the retina\'s light-sensing cells. Their outer part is full of membranes carrying a light-sensitive protein with retinal. A photon changes retinal\'s shape and starts a chain of events that ends in a nerve signal. Use the button to see retinal.', 'Birds have rods for dim light and cones, with several kinds for colour.', 'Sizes drawn are illustrative.', [['Light-catching molecule', 'retinal']], refs=[R_VIS], ext=[WBA], related=['rod_cell', 'cone_cell', 'vision'])
T('robin_cryptochrome', 'Cryptochrome 4 (a hypothesis for the magnetic sensor)', 5e-9, ['robin_retina_scene'], 'A light-sensitive protein that carries the molecule FAD; it is a candidate for the robin\'s magnetic sensor.', 'Cryptochrome is a protein that holds a flavin molecule (FAD). When light excites the FAD, an electron jumps along a chain of tryptophan units in the protein, leaving a pair of molecules with unpaired electrons. Earth\'s magnetic field could affect how long such a pair lasts. This is a hypothesis for how a robin senses the field, not a proved mechanism. Use the button to see FAD.', 'In the laboratory, robin cryptochrome 4 shows a four-step electron transfer and long-lived radical pairs. Whether it works as the compass in the bird is not shown.', 'See the compass card for the evidence and what is missing.', [['Cofactor', 'FAD'], ['Status', 'hypothesis (in vitro evidence)']], cert='C3', refs=[R_SENS], ext=[XU, WONG, HORE], openq=['Is cryptochrome 4 the magnetic sensor in the living robin eye?'], related=['robin_compass'])

# ------------------------------------------------ the park-level card (kept id; it now leads to the robin)
N('park_bird', 'Bird', 'organism', .14, ['park_scene'],
  'A bird is a feathered animal descended from theropod dinosaurs; the park\'s bird is a European robin, standing on the boulder.',
  'Birds are the living descendants of feathered dinosaurs. Most fly, with wings, hollow bones, a keeled breastbone and a lung that works with air sacs; some, such as ostriches, do not. The bird in this park is a European robin, standing on the boulder. Click it for its card, or use "Show where it is" to fly to it.',
  'Birds are theropod dinosaurs, warm-blooded, with feathers, a four-chambered heart and a lung in which air flows in one direction. Zoom in on the robin to see all of that, down to the molecules of its feathers and muscles.',
  'The old cartoon birds are gone; the robin is a data model built to true size. The park is a simplified scene, not a scan of a real place.',
  [['Shown here', 'a European robin, about 14 cm long'], ['Birds', 'over 11,000 living species in 44 orders (Wikipedia, Bird)']], cert='C1', refs=[R_BIRD], ext=[BIRD], parts=['robin'], related=['bio_reptiles_birds', 'bio_evolution_of_flight'])
